out<-"analysis/gamewell_secondary_ls_2026-10-16";rds<-file.path(out,"life_satisfaction_fit1_full.rds");if(!file.exists(rds))stop("Fit 1 saved model object is missing; no refit will be attempted.")
for(nm in c("FIT1_RESIDUAL_SUMMARY.csv","FIT1_RESIDUALS_BY_FITTED_BINS.csv","fit1_residual_histogram.svg","fit1_residual_qq.svg","fit1_residuals_vs_fitted.svg"))if(file.exists(file.path(out,nm)))stop(paste("Refusing overwrite:",nm))
fit<-readRDS(rds);res<-as.numeric(residuals(fit));fv<-as.numeric(fitted(fit));s<-sd(res);summ<-data.frame(n=length(res),mean=mean(res),SD=s,skewness=mean((res-mean(res))^3)/s^3,excess_kurtosis=mean((res-mean(res))^4)/s^4-3,q01=unname(quantile(res,.01)),q05=unname(quantile(res,.05)),q25=unname(quantile(res,.25)),median=unname(quantile(res,.5)),q75=unname(quantile(res,.75)),q95=unname(quantile(res,.95)),q99=unname(quantile(res,.99)),stringsAsFactors=FALSE);write.csv(summ,file.path(out,"FIT1_RESIDUAL_SUMMARY.csv"),row.names=FALSE)
bin<-pmin(10L,ceiling(rank(fv,ties.method="average")/length(fv)*10));bins<-do.call(rbind,lapply(sort(unique(bin)),function(k){i<-bin==k;data.frame(fitted_bin=k,n=sum(i),mean_fitted=mean(fv[i]),mean_residual=mean(res[i]),residual_SD=sd(res[i]))}));write.csv(bins,file.path(out,"FIT1_RESIDUALS_BY_FITTED_BINS.csv"),row.names=FALSE)
grDevices::svg(file.path(out,"fit1_residual_histogram.svg"),width=7,height=5);hist(res,breaks="FD",main="Life-satisfaction Fit 1 residuals",xlab="Residual",col="grey80",border="white");grDevices::dev.off();grDevices::svg(file.path(out,"fit1_residual_qq.svg"),width=7,height=5);qqnorm(res,main="Life-satisfaction Fit 1 residual Q-Q plot");qqline(res,col="red",lwd=2);grDevices::dev.off();grDevices::svg(file.path(out,"fit1_residuals_vs_fitted.svg"),width=7,height=5);plot(bins$mean_fitted,bins$mean_residual,pch=19,xlab="Mean fitted value (decile bins)",ylab="Mean residual",main="Fit 1 residuals by fitted decile");abline(h=0,col="red",lwd=2);grDevices::dev.off();cat("Fit 1 residual diagnostics saved; no refit performed.\n")